meta:
, and
    scripts/ci/homepage-check fails the build if the two ever disagree. -#}
{%- set nav_declaration = load_data(path="data/nav.toml") -%}
{%- set indexing = nav_declaration.indexing -%}

{%- for entry in entries %}
{%- set path_parts = entry.permalink | replace(from=config.base_url, to="") | split(pat="/") -%}
{%- set unlisted = path_parts | length >= 4 and path_parts[1] in indexing.unlisted -%}
{%- set own = entry.extra is defined and entry.extra and entry.extra.noindex is defined and entry.extra.noindex -%}
{%- if not unlisted and not own %}
  {{ entry.permalink | escape_xml | safe }}{% if entry.updated %}{{ entry.updated }}{% endif %}
{%- endif %}
{%- endfor %}
